"""Skill-routed evidence update for the bounded response pilot, preserving candidate status."""
from pathlib import Path
import sys,json,re
ROOT=Path(__file__).resolve().parents[2]
sys.path.insert(0,str(ROOT/'src/preprocessing'))
from prepare_reference_setup_pilot import REPORT
from prepare_sfincs_cpu_build import sha,dump

def main():
 report=ROOT/REPORT;s=json.loads((report/'summary.json').read_text());assert s['new_pilot_responses_completed']==8 and s['primary_grid_qualification_passed'];eligible=len(s['numerically_eligible_pilot_cases']);held=len(s['held_pilot_cases']);p=ROOT/'docs/AnaSOP.md';backup=report/'previous-AnaSOP.md'
 if not backup.exists():backup.write_bytes(p.read_bytes())
 before=backup.read_text();parts=re.split(r'(?=^## [1-8]\. )',before,flags=re.M);assert all(any(x.startswith('## '+str(k)+'.')for x in parts)for k in [1,3,4,8])
 additions={3:f'The subsequent bounded primary-grid setup now adds ten versioned regular-grid response packages: two replays of existing open controls and eight preselected prospective pilot inputs. The pilot contains four training parents, two validation parents and two open controls sharing the legacy family; it contributes six new parent candidates, not eight independent storms. Each completed package retains forty-nine full-field snapshots, actual-step and output clocks, native online peaks and reconstructed common-ground depth bounds with the original quality masks. Of the eight pilot responses, {eligible} pass the complete numerical review and {held} remain held. The original forcing-only execution list is preserved as a historical snapshot; a separate current index records the eight executed regular-grid descendants and fifty unexecuted descendants, comprising forty-two regular and eight adaptive runs. No sealed or challenge responses, training or measured-event validation are generated.',4:'Reconstruct the new regular-grid Peak Mean Depth lower and upper bounds over exactly the same original eligible ground, and retain native shallow censoring, assumed-barrier contact and actual-step negative-volume evidence. Reapply the frozen exact and narrow-interval policy per event; wider intervals and quarantined support remain excluded. Ground Elevation, Ground Area, Building Occupancy, Road Connectivity and prescribed forcing inputs remain unchanged. All reference-quality information stays on the supervision side. No variable is finalized, no midpoint or dry-zero target is substituted and no learned normalization is fitted.',5:'The approved setup tranche is now implemented as two legacy-control qualification replays followed conditionally by eight regular-grid pilot responses: the two new deterministic controls, four training parents covering early, central, late and multiple-peak shapes, and two predesignated validation parents. Selection was frozen before responses. Validation numerical auditing does not authorize model fitting, and test and challenge responses remain closed. This tranche does not execute the eight proposed adaptive companions or the remaining regular-grid cases. Controls continue to share the legacy family and are excluded from independent-parent claims.',6:f'The exact-rainfall solver now passes the original primary-grid control gates as well as the previously corrected adaptive controls. Compare both grids on identical original-ground support, with peak aggregation intervals and gross bidirectional receiving-water exchange retained; do not infer formal convergence from two grids. The eight-input regular-grid pilot provides {eligible} numerically eligible candidate response packages and {held} held packages under the unchanged event and cell rules. Report per-ward exact, narrow-interval, wide and quarantined area, input-curve versus applied rain volume, same-step budget residual and actual output timing. Six new parent candidates are a setup sample, not proof of sufficient learning diversity or surrogate performance. Real-world accuracy, full channel dynamics and dynamic internal-flow labels remain unverified.',7:'The two legacy regular-grid controls have completed qualification and corrected-grid comparison, followed by exactly eight preselected regular-grid pilot executions and per-event label audits. Keep the original forcing catalog, partitions and earlier responses frozen, with the current execution overlay distinguishing completed, held and unrun cases. Preserve the remaining fifty descendants and sealed response custody. No automatic batch expansion, training or formal reference release follows from the pilot. Review Reference uncertainty and Scenario coverage and split audit evidence before any separately scoped library expansion or learning stage. Active measures remain Milestone 5, after the first four milestones.'}
 for i,part in enumerate(parts):
  if part.startswith('## '):
   k=int(re.match(r'## (\d)',part).group(1))
   if k in additions:parts[i]=part.rstrip()+'\n\n'+additions[k]+'\n\n'
 after=''.join(parts);assert after.isascii();p.write_text(after);dump(report/'anasop-update.json',{'sections_changed':[3,4,5,6,7],'skills':['data-briefing','data-preprocessing','estimation-framework-planning'],'human_record':'MILI-D-20261015-017','prior_sha256':sha(backup),'current_sha256':sha(p),'new_final_variables':0,'new_formulas':0,'other_sections_unchanged':True,'Section8_outputs':'Domain and data readiness; Reference uncertainty; Scenario coverage and split audit','real_world_accuracy_verified':False})
 print('Skill-routed AnaSOP Sections3-7 updated; other sections unchanged; English/ASCII checked.')
if __name__=='__main__':main()
